ALTER TABLE "driver_profiles" ADD COLUMN "risk_status" VARCHAR(20) NOT NULL DEFAULT 'clear', ADD COLUMN "suspension_reason" VARCHAR(500), ADD COLUMN "suspended_at" TIMESTAMP(6);
ALTER TABLE "driver_profiles" ADD CONSTRAINT "driver_profiles_risk_status_check" CHECK ("risk_status" IN ('clear','flagged','suspended'));
CREATE TABLE "driver_incidents" ("id" SERIAL PRIMARY KEY,"reference" VARCHAR(30) NOT NULL UNIQUE,"driver_id" INTEGER NOT NULL,"ride_id" INTEGER,"category" VARCHAR(30) NOT NULL,"priority" VARCHAR(20) NOT NULL DEFAULT 'normal',"description" VARCHAR(2000) NOT NULL,"evidence_urls" JSONB NOT NULL DEFAULT '[]',"status" VARCHAR(30) NOT NULL DEFAULT 'open',"assigned_to_id" INTEGER,"resolution_note" VARCHAR(2000),"resolved_by_id" INTEGER,"resolved_at" TIMESTAMP(6),"created_at" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "driver_incidents_driver_id_fkey" FOREIGN KEY("driver_id") REFERENCES "driver_profiles"("id") ON DELETE CASCADE,CONSTRAINT "driver_incidents_ride_id_fkey" FOREIGN KEY("ride_id") REFERENCES "rides"("id") ON DELETE SET NULL,CONSTRAINT "driver_incidents_assigned_to_id_fkey" FOREIGN KEY("assigned_to_id") REFERENCES "users"("id") ON DELETE SET NULL,CONSTRAINT "driver_incidents_resolved_by_id_fkey" FOREIGN KEY("resolved_by_id") REFERENCES "users"("id") ON DELETE SET NULL,CONSTRAINT "driver_incidents_category_check" CHECK("category" IN ('accident','passenger_issue','vehicle_damage','safety_concern','lost_item','other')),CONSTRAINT "driver_incidents_priority_check" CHECK("priority" IN ('normal','high','emergency')),CONSTRAINT "driver_incidents_status_check" CHECK("status" IN ('open','investigating','resolved','dismissed')));
CREATE INDEX "idx_driver_incidents_queue" ON "driver_incidents"("status","priority","created_at" DESC); CREATE INDEX "idx_driver_incidents_driver" ON "driver_incidents"("driver_id","created_at" DESC);
CREATE TABLE "driver_shifts" ("id" SERIAL PRIMARY KEY,"driver_id" INTEGER NOT NULL,"started_at" TIMESTAMP(6) NOT NULL,"ended_at" TIMESTAMP(6),CONSTRAINT "driver_shifts_driver_id_fkey" FOREIGN KEY("driver_id") REFERENCES "driver_profiles"("id") ON DELETE CASCADE); CREATE INDEX "idx_driver_shifts_driver" ON "driver_shifts"("driver_id","started_at" DESC);
CREATE TABLE "driver_risk_actions" ("id" SERIAL PRIMARY KEY,"driver_id" INTEGER NOT NULL,"action" VARCHAR(30) NOT NULL,"reason" VARCHAR(500) NOT NULL,"created_by_id" INTEGER NOT NULL,"created_at" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "driver_risk_actions_driver_id_fkey" FOREIGN KEY("driver_id") REFERENCES "driver_profiles"("id") ON DELETE CASCADE,CONSTRAINT "driver_risk_actions_created_by_id_fkey" FOREIGN KEY("created_by_id") REFERENCES "users"("id") ON DELETE RESTRICT); CREATE INDEX "idx_driver_risk_actions_driver" ON "driver_risk_actions"("driver_id","created_at" DESC);
